CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own profile read" ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY "own profile update" ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE OR REPLACE FUNCTION public.create_owner_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); RETURN new; END $$;
CREATE TRIGGER on_auth_user_created_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_owner_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,coalesce(raw_user_meta_data->>'display_name','') FROM auth.users ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.grant_first_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN new; END $$;
ALTER TABLE public.businesses ADD COLUMN segment text NOT NULL DEFAULT 'Salão', ADD COLUMN trial_ends_at timestamptz, ADD COLUMN subscription_status text NOT NULL DEFAULT 'legacy';
ALTER TABLE public.services ADD COLUMN duration_minutes integer NOT NULL DEFAULT 60, ADD COLUMN price_cents integer NOT NULL DEFAULT 0;
CREATE TABLE public.tenant_settings (business_id uuid PRIMARY KEY REFERENCES public.businesses(id) ON DELETE CASCADE, open_time text NOT NULL DEFAULT '09:00', close_time text NOT NULL DEFAULT '18:00', lunch_start text, lunch_end text, service_minutes integer NOT NULL DEFAULT 60, slot_interval_minutes integer NOT NULL DEFAULT 60, open_weekdays integer[] NOT NULL DEFAULT '{1,2,3,4,5,6}');
GRANT SELECT ON public.tenant_settings TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.tenant_settings TO authenticated;
GRANT ALL ON public.tenant_settings TO service_role;
ALTER TABLE public.tenant_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public tenant settings" ON public.tenant_settings FOR SELECT USING(true);
CREATE POLICY "owner tenant settings" ON public.tenant_settings FOR ALL TO authenticated USING(public.is_business_owner(business_id)) WITH CHECK(public.is_business_owner(business_id));
DROP POLICY "admin all appointments" ON public.appointments;
CREATE POLICY "owner appointments" ON public.appointments FOR ALL TO authenticated USING(public.is_business_owner(business_id)) WITH CHECK(public.is_business_owner(business_id));
DROP POLICY "admin write services" ON public.services;
CREATE POLICY "owner services" ON public.services FOR ALL TO authenticated USING(public.is_business_owner(business_id)) WITH CHECK(public.is_business_owner(business_id));
DROP POLICY "admin write blocked" ON public.blocked_dates;
CREATE POLICY "owner blocked" ON public.blocked_dates FOR ALL TO authenticated USING(public.is_business_owner(business_id)) WITH CHECK(public.is_business_owner(business_id));
DROP POLICY "admin update settings" ON public.business_settings;
CREATE POLICY "owner legacy settings" ON public.business_settings FOR UPDATE TO authenticated USING(public.is_business_owner(business_id)) WITH CHECK(public.is_business_owner(business_id));
DROP INDEX public.appointments_unique_active_slot;
CREATE OR REPLACE FUNCTION public.create_business(_name text,_slug text,_whatsapp text,_segment text,_plan text,_services jsonb,_open text,_close text,_interval integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b uuid; s jsonb; BEGIN
IF auth.uid() IS NULL OR length(trim(_name))<2 OR _slug !~ '^[a-z0-9][a-z0-9-]{2,60}$' OR length(regexp_replace(_whatsapp,'\D','','g'))<10 OR _plan NOT IN ('solo','pro','classes') OR _interval<5 OR _interval>480 OR _open::time>=_close::time OR jsonb_array_length(_services)<1 THEN RAISE EXCEPTION 'invalid'; END IF;
IF EXISTS(SELECT 1 FROM public.businesses WHERE owner_id=auth.uid()) THEN RAISE EXCEPTION 'business_exists'; END IF;
INSERT INTO public.businesses(owner_id,name,slug,whatsapp,segment,plan,trial_ends_at,subscription_status) VALUES(auth.uid(),trim(_name),_slug,regexp_replace(_whatsapp,'\D','','g'),_segment,_plan,now()+interval '5 days','trial') RETURNING id INTO b;
INSERT INTO public.tenant_settings(business_id,open_time,close_time,slot_interval_minutes) VALUES(b,_open,_close,_interval);
INSERT INTO public.professionals(business_id,name) VALUES(b,coalesce(nullif((SELECT display_name FROM public.profiles WHERE id=auth.uid()),''),'Responsável'));
FOR s IN SELECT * FROM jsonb_array_elements(_services) LOOP
IF length(trim(s->>'name'))<2 OR (s->>'duration')::integer<5 OR (s->>'duration')::integer>480 OR (s->>'price')::integer<0 THEN RAISE EXCEPTION 'invalid_service'; END IF;
INSERT INTO public.services(business_id,name,duration_minutes,price_cents) VALUES(b,s->>'name',(s->>'duration')::integer,(s->>'price')::integer); END LOOP; RETURN b; END $$;
REVOKE ALL ON FUNCTION public.create_business(text,text,text,text,text,jsonb,text,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_business(text,text,text,text,text,jsonb,text,text,integer) TO authenticated;